export type { RunKey };

type Env = Record<string, string | undefined>;

const OPENROUTER_BASE_URL = "https://openrouter.ai/api/v1";

const runKey = (requestedModel: string): RunKey => ({
  requestedModel,
  promptVersion: PROMPT_VERSION,
  taxonomyVersion: TAXONOMY_VERSION,
});

export function llmMode(env: Env = process.env): "mock" | "live" {
  const mode = env.LLM_MODE || "mock";
  if (mode !== "mock" && mode !== "live") {
    throw new Error(`LLM_MODE must be "mock" or "live", not "${mode}"`);
  }
  return mode;
}

/** The run key of the worker, the API and the UI: mock → 'mock', live → ENRICH_MODEL. */
export function activeRunKey(env: Env = process.env): RunKey {
  if (llmMode(env) === "mock") return runKey("mock");
  if (!env.ENRICH_MODEL) {
    throw new Error("LLM_MODE=live needs ENRICH_MODEL");
  }
  return runKey(env.ENRICH_MODEL);
}

/**
 * The run key of the read-only scripts (score, metrics): ENRICH_MODEL if set,
 * otherwise mock. They do not read LLM_MODE and need no key (deviation 8).
 */
export function readOnlyRunKey(env: Env = process.env): RunKey {
  return runKey(env.ENRICH_MODEL || "mock");
}

/** Live mode fails here, at startup, without a key and a model. */
export function createProvider(env: Env = process.env): EnrichmentProvider {
// Query text → tokens (spec §2, Grammar):
//
//   PHRASE := '"' [^"]+ '"'
//   PREFIX := TERM '*'
//   TERM   := [^\s()"*]+      -- but not exactly AND / OR / NOT
//
// Operators are case-sensitive (R7): `AND` is an operator, `and` is a term.
// A term, prefix or phrase with no letter or digit is rejected here (deviation 3):
// it has no lexeme under either text-search config, so it could never match.
// A query that contains U+0000 is rejected too (deviation 16).

/** A query the grammar or the limits reject. Maps to HTTP 400 `invalid_query`. */
export class InvalidQueryError extends Error {
  readonly code = "invalid_query";
  constructor(message: string) {
    super(message);
    this.name = "InvalidQueryError";
  }
}

export type Token =
  | { type: "lparen" | "rparen" | "and" | "or" | "not" }
  | { type: "term" | "prefix" | "phrase"; text: string };

const OPERATORS: Record<string, "and" | "or" | "not"> = {
  AND: "and",
  OR: "or",
  NOT: "not",
};
const WORD = /[^\s()"*]+/y;
const LETTER_OR_DIGIT = /[\p{L}\p{N}]/u;

/** Quotes a token for an error message, shortened so a message stays short. */
export function shown(text: string): string {
  const chars = [...text];
  const out: Finding[] = [];
  codeLines(text).forEach((line, i) => {
    if (NETWORK_CALL.test(line) || NETWORK_IMPORT.test(line)) {
      out.push({ rule: "mock-no-fetch", file, line: i + 1 });
    }
  });
  return out;
}

export function noSqlInRoutes(file: string, text: string): Finding[] {
  const out: Finding[] = [];
  codeLines(text).forEach((line, i) => {
    if (
      DB_IMPORT.test(line) ||
      QUERY_CALL.test(line) ||
      SQL_STATEMENT.test(line)
    ) {
      out.push({ rule: "no-sql-in-routes", file, line: i + 1 });
    }
  });
  return out;
}

export function noStringBuiltSql(file: string, text: string): Result {
  const rule = "no-string-built-sql";
  const raw = text.split("\n");
  const lines = codeLines(text);
  const suspect = new Set<number>(); // 0-based line indexes

  // Template literals, taken whole: SQL on one line and `${…}` on another still counts.
  const code = lines.join("\n");
  const template = /`[^`]*`/g;
  for (let m = template.exec(code); m; m = template.exec(code)) {
    if (!isSql(m[0]) || !m[0].includes("${")) continue;
    const first = code.slice(0, m.index).split("\n").length - 1;
    m[0].split("\n").forEach((part, offset) => {
      if (part.includes("${")) suspect.add(first + offset);
    });
  }
  // String concatenation on a line that holds SQL text.
  lines.forEach((line, i) => {
    if (CONCATENATION.test(line) && isSql(line)) suspect.add(i);
  });

  const result: Result = { violations: [], allowances: [] };
  for (const i of [...suspect].sort((a, b) => a - b)) {
    const marker = MARKER.exec(raw[i] ?? "") ?? MARKER.exec(raw[i - 1] ?? "");
    const reason = marker?.[1]?.replace(/^[\s—:-]+/, "").trim();
    if (reason)
      result.allowances.push({ rule, file, line: i + 1, note: reason });
    else result.violations.push({ rule, file, line: i + 1 });
