  call(aggregateRoute, "/api/articles/aggregate", params);

const ids = (body: Json) =>
  (body.items as Item[]).map((item) => item.id).sort((a, b) => a - b);
const total = (body: Json) =>
  (body.buckets as BucketRow[]).reduce((sum, row) => sum + row.count, 0);

