     FROM (VALUES (1, 'negative', ARRAY['energy', 'geopolitics']),
                  (5, 'positive', ARRAY['energy', 'climate']),
                  (10, 'positive', ARRAY['ai', 'health'])) AS v (external_id, sentiment, tags)
