      expect(status).toBe(200);
      seen.push(...(body.items as Item[]).map((item) => item.id));
      cursor = body.next_cursor as string | null;
      pages += 1;
    } while (cursor && pages < 10);
    expect(pages).toBe(3);
    expect(seen).toHaveLength(20);
    expect(new Set(seen).size).toBe(20);
  });

