    expect(ids((await articles({ sentiment: "positive" })).body)).toEqual([
      5, 10,
    ]);
    expect(ids((await articles({ topic: "energy" })).body)).toEqual([1, 5]);
    expect(
      ids((await articles({ topic: "energy", sentiment: "negative" })).body),
    ).toEqual([1]);
  });

